public class Solution {
    public int minSpeedOnTime(int[] dist, double hour) {
        if (dist.length == 1) {
            double speed = (double) dist[0] / hour;
            return (int) Math.ceil(speed);
        }

        int left = 1;
        int right = 10000000;
        int ans = -1;

        while (left <= right) {
            int mid = left + (right - left) / 2;
            double time = 0;
            for (int i = 0; i < dist.length - 1; i++) {
                time += Math.ceil((double) dist[i] / mid);
            }
            time += (double) dist[dist.length - 1] / mid;

            if (time <= hour) {
                ans = mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        return ans;
    }
}

