public class Solution {
    public int getNumberOfBacklogOrders(int[][] orders) {
        PriorityQueue<int[]> buyOrders = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        PriorityQueue<int[]> sellOrders = new PriorityQueue<>(Comparator.comparingInt(a -> -a[0]));
        long totalRemaining = 0;
        int MOD = 1000000007;

        for (int[] order : orders) {
            int price = order[0];
            int amount = order[1];
            int orderType = order[2];

            if (orderType == 0) { // Buy order
                while (!sellOrders.isEmpty() && sellOrders.peek()[0] <= price) {
                    int[] sellOrder = sellOrders.poll();
                    int matchAmount = Math.min(amount, sellOrder[1]);
                    amount -= matchAmount;
                    sellOrder[1] -= matchAmount;
                    if (sellOrder[1] > 0) {
                        sellOrders.offer(sellOrder);
                    }
                    if (amount == 0) {
                        break;
                    }
                }
                if (amount > 0) {
                    buyOrders.offer(new int[]{price, amount});
                }
            } else { // Sell order
                while (!buyOrders.isEmpty() && buyOrders.peek()[0] >= price) {
                    int[] buyOrder = buyOrders.poll();
                    int matchAmount = Math.min(amount, buyOrder[1]);
                    amount -= matchAmount;
                    buyOrder[1] -= matchAmount;
                    if (buyOrder[1] > 0) {
                        buyOrders.offer(buyOrder);
                    }
                    if (amount == 0) {
                        break;
                    }
                }
                if (amount > 0) {
                    sellOrders.offer(new int[]{price, amount});
                }
            }
        }

        for (int[] order : buyOrders) {
            totalRemaining = (totalRemaining + order[1]) % MOD;
        }
        for (int[] order : sellOrders) {
            totalRemaining = (totalRemaining + order[1]) % MOD;
        }

        return (int) totalRemaining;
    }
}

