public class Solution {
    public int getMinSwaps(String num, int k) {
        char[] digits = num.toCharArray();
        int n = digits.length;
        int swaps = 0;

        if (k == 1) {
            return 0;
        }

        for (int i = 0; i < k; i++) {
            int j = n - 2;
            while (j >= 0 && digits[j] >= digits[j + 1]) {
                j--;
            }

            if (j < 0) {
                break;
            }

            int l = n - 1;
            while (digits[l] <= digits[j]) {
                l--;
            }

            swap(digits, j, l);
            reverse(digits, j + 1, n - 1);
            swaps++;
        }

        return swaps;
    }

    private void swap(char[] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    private void reverse(char[] arr, int start, int end) {
        while (start < end) {
            swap(arr, start, end);
            start++;
            end--;
        }
    }
}

