    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        if (firstPlayer == secondPlayer) {
            return new int[]{-1, -1};
        }

        int earliest = -1;
        int latest = -1;

        List<Integer> players = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            players.add(i);
        }

        int round = 1;
        while (players.size() > 1) {
            List<Integer> nextRoundPlayers = new ArrayList<>();
            for (int i = 0; i < players.size() / 2; i++) {
                int left = players.get(i);
                int right = players.get(players.size() - 1 - i);

                int winner;
                if (left == firstPlayer && right == secondPlayer) {
                    winner = firstPlayer;
                    if (earliest == -1) {
                        earliest = round;
                    }
                    latest = round;
                } else if (right == firstPlayer && left == secondPlayer) {
                    winner = firstPlayer;
                    if (earliest == -1) {
                        earliest = round;
                    }
                    latest = round;
                } else {
                    winner = (left < right) ? left : right;
                }
                nextRoundPlayers.add(winner);
            }

            if (players.size() % 2 != 0) {
                nextRoundPlayers.add(players.get(players.size() / 2));
            }

            players = nextRoundPlayers;
            round++;
        }

        return new int[]{earliest, latest};
    }
