    public int minFlips(String s) {
        int n = s.length();
        int flips1 = 0;
        int flips2 = 0;

        // Calculate flips for "0101..." pattern
        for (int i = 0; i < n; i++) {
            if (i % 2 == 0 && s.charAt(i) == '1') {
                flips1++;
            } else if (i % 2 != 0 && s.charAt(i) == '0') {
                flips1++;
            }
        }

        // Calculate flips for "1010..." pattern
        for (int i = 0; i < n; i++) {
            if (i % 2 == 0 && s.charAt(i) == '0') {
                flips2++;
            } else if (i % 2 != 0 && s.charAt(i) == '1') {
                flips2++;
            }
        }

        return Math.min(flips1, flips2);
    }
}

