        for (int[] log : logs) {
            int userId = log[0];
            int time = log[1];
            if (!userToMinutes.containsKey(userId)) {
                userToMinutes.put(userId, new HashSet<>());
            }
            userToMinutes.get(userId).add(time);
        }

        int[] uamCounts = new int[k + 1];
