            int uam = userToMinutes.get(userId).size();
            uamCounts[uam]++;
        }

        int[] answer = new int[k];
        for (int i = 1; i <= k; i++) {
            answer[i - 1] = uamCounts[i];
        }

        return answer;
    }
}

