                            break;
                        }
                    }
                    if (valid) {
                        j = k;
                        break;
                    }
                }
            }

            if (j != -1) {
                char temp = chars[i];
                chars[i] = chars[j];
                chars[j] = temp;

                reverse(chars, i + 1, n - 1);
                operations = (operations + 1) % mod;
            }
        }

        return (int) operations;
    }

    private void reverse(char[] chars, int start, int end) {
        while (start < end) {
            char temp = chars[start];
            chars[start] = chars[end];
            chars[end] = temp;
            start++;
            end--;
        }
    }
}

package referenz;

import java.util.Arrays;

public class Solution {
    public int rearrangeSticks(int n, int k) {
        long mod = 1000000007;
        long[][] dp = new long[n + 1][k + 1];

        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= k; j++) {
                dp[i][j] = 0;

                // Case 1: Stick i is not visible
                if (j > 0) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j]) % mod;
                }

                // Case 2: Stick i is visible
                if (j > 0 && j <= k) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % mod;
                } else if (j == 0) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j]) % mod;
                }
            }
        }

        return (int) dp[n][k];
    }
}

