import java.util.Arrays;

public class Solution {
    public int minSwaps(String s) {
        int n = s.length();
        if (n == 0) {
            return 0;
        }
        if (n == 1) {
            return 0;
        }

        int zeros = 0;
        int ones = 0;
        for (char c : s.toCharArray()) {
            if (c == '0') {
                zeros++;
            } else {
                ones++;
            }
        }

        if (Math.abs(zeros - ones) > 1) {
            return -1;
        }

        int swaps = 0;
        if (zeros > ones) {
            for (int i = 0; i < n; i++) {
                if (i % 2 == 0 && s.charAt(i) == '1') {
                    swaps++;
                } else if (i % 2 != 0 && s.charAt(i) == '0') {
                    swaps++;
                }
            }
        } else if (ones > zeros) {
            for (int i = 0; i < n; i++) {
                if (i % 2 == 0 && s.charAt(i) == '0') {
                    swaps++;
                } else if (i % 2 != 0 && s.charAt(i) == '1') {
                    swaps++;
                }
            }
        } else {
            int swaps0 = 0;
            for (int i = 0; i < n; i++) {
                if (i % 2 == 0 && s.charAt(i) == '1') {
                    swaps0++;
                } else if (i % 2 != 0 && s.charAt(i) == '0') {
                    swaps0++;
                }
            }

            int swaps1 = 0;
            for (int i = 0; i < n; i++) {
                if (i % 2 == 0 && s.charAt(i) == '0') {
                    swaps1++;
                } else if (i % 2 != 0 && s.charAt(i) == '1') {
                    swaps1++;
                }
            }
            swaps = Math.min(swaps0, swaps1);
        }

        return swaps;
    }
}
